// Anthropic returns content as an array of blocks, not choices[0].message.content.
// Thinking is ON BY DEFAULT on Claude Opus 5, so the array contains thinking blocks
// alongside the text block — take the text blocks specifically rather than index 0.
const blocks = $input.first().json.content || [];
const text = blocks
  .filter(b => b && b.type === 'text')
  .map(b => b.text)
  .join('')
  .trim();

let ratings = [];
try {
  const a = text.indexOf('['); const b = text.lastIndexOf(']');
  if (a >= 0 && b > a) ratings = JSON.parse(text.slice(a, b + 1));
} catch { ratings = []; }

// One item per rating so the PATCH runs as a normal HTTP Request node with the
// Supabase credential attached. The previous version wrote to Supabase from inside
// this Code node using $credentials, which n8n removed from Code nodes — that is the
// "$credentials is not defined" failure. Doing the write in an HTTP Request node also
// means the service key never has to appear in code.
const now = new Date().toISOString();
return ratings
  .filter(r => r && r.id)
  .map(r => ({ json: {
    id: r.id,
    lever_score: r.lever_score,
    est_hours_to_revenue: r.est_hours_to_revenue,
    lever_rated_at: now,
  } }));

// Supabase returns a JSON array, and n8n splits an array response into one item
// per row — so without this node the HTTP Request below fires once PER TASK. The
// 16:04 run made 20 separate Opus calls and the parser read only the first,
// discarding 19. The prompt was always written for a batch ("one per input task"),
// so collapse the rows back into a single item and make one call.
return [{ json: { tasks: $input.all().map(i => i.json) } }];
